100→
101→  /* Layout - balanced width */
102→  --max-content-width: 1600px;
103→  --side-padding: clamp(24px, 3vw, 80px);     /* Fluid: scales with viewport */
104→  --side-padding-md: clamp(34px, 4vw, 100px);  /* Fluid: scales with viewport */
