373→/* ===========================================
374→   VIEW TRANSITIONS - Cinematic Page Crossfades
375→   =========================================== */
376→
377→/*
378→ * Design philosophy:
379→ * - Film dissolve feel, not flashy web animation
380→ * - Content: subtle crossfade with micro-scale for depth
381→ * - Navigation: fade only (no scale/position change - stays anchored)
382→ * - Duration: 500ms content, 400ms nav (slow enough to feel intentional)
383→ * - Easing: ease-in-out for cinematic linear-ish blend
384→ */
385→
386→/* Dark canvas behind all transition layers — prevents white bleed-through */
387→::view-transition {
388→  background-color: #141414;
389→}
390→
391→::view-transition-group(root),
392→::view-transition-group(navigation),
393→::view-transition-group(footer) {
394→  background-color: #141414;
395→}
396→
397→/* Root (main content) transition */
398→::view-transition-old(root),
399→::view-transition-new(root) {
400→  animation-duration: 500ms;
401→  animation-timing-function: ease-in-out;
402→}
403→
404→/* Old page: fade out with slight scale down */
405→::view-transition-old(root) {
406→  animation-name: fade-and-scale-out;
407→}
408→
409→/* New page: fade in with slight scale up */
410→::view-transition-new(root) {
411→  animation-name: fade-and-scale-in;
412→}
413→
414→@keyframes fade-and-scale-out {
415→  from {
416→    opacity: 1;
417→    transform: scale(1);
418→  }
419→  to {
420→    opacity: 0;
421→    transform: scale(0.98);
422→  }
423→}
424→
425→@keyframes fade-and-scale-in {
426→  from {
427→    opacity: 0;
428→    transform: scale(1.02);
429→  }
430→  to {
431→    opacity: 1;
432→    transform: scale(1);
433→  }
434→}
435→
436→/* Navigation: fade only, no scale (stays anchored) */
437→::view-transition-old(navigation),
438→::view-transition-new(navigation) {
439→  animation-duration: 400ms;
440→  animation-timing-function: ease-in-out;
441→}
442→
443→::view-transition-old(navigation) {
444→  animation-name: fade-out-only;
445→}
446→
447→::view-transition-new(navigation) {
448→  animation-name: fade-in-only;
449→}
450→
451→/* Hero reel: fade only, no scale (prevents white flash from iframe reinit) */
452→/* Dark background on the transition group prevents white bleed-through during crossfade */
453→::view-transition-group(hero-reel) {
454→  background-color: #141414;
455→}
456→
457→::view-transition-old(hero-reel),
458→::view-transition-new(hero-reel) {
459→  animation-duration: 400ms;
460→  animation-timing-function: ease-in-out;
461→}
462→
463→::view-transition-old(hero-reel) {
464→  animation-name: fade-out-only;
465→}
466→
467→::view-transition-new(hero-reel) {
468→  animation-name: fade-in-only;
469→}
470→
471→/* Footer: fade only, no scale (stays anchored) */
472→::view-transition-old(footer),
473→::view-transition-new(footer) {
474→  animation-duration: 400ms;
475→  animation-timing-function: ease-in-out;
476→}
477→
478→::view-transition-old(footer) {
479→  animation-name: fade-out-only;
480→}
481→
482→::view-transition-new(footer) {
483→  animation-name: fade-in-only;
484→}
485→
486→@keyframes fade-out-only {
487→  from { opacity: 1; }
488→  to { opacity: 0; }
489→}
490→
491→@keyframes fade-in-only {
492→  from { opacity: 0; }
493→  to { opacity: 1; }
494→}
