'use client';

/**
 * Perception Layer
 * Phase 2: USD Substrate Integration
 *
 * Wraps the app with perception context and runs the sensor site-wide.
 * All events (browsing + chat) feed into a shared classifier.
 */

import { ReactNode, useState, useEffect } from 'react';
import { PerceptionProvider, usePerception } from '@/lib/perception/context';
import { PerceptionSensor } from '@/components/PerceptionSensor';
import { PerceptionIndicator } from '@/components/PerceptionIndicator';

function PerceptionSensorBridge() {
  const { recordEvent, sessionId, perceptionState } = usePerception();
  const [showDebug, setShowDebug] = useState(false);

  // Check for debug mode
  useEffect(() => {
    if (typeof window !== 'undefined') {
      const params = new URLSearchParams(window.location.search);
      setShowDebug(params.get('debug') === 'perception');
    }
  }, []);

  return (
    <>
      <PerceptionSensor recordEvent={recordEvent} sessionId={sessionId} />
      <PerceptionIndicator perceptionState={perceptionState} enabled={showDebug} />
    </>
  );
}

export function PerceptionLayer({ children }: { children: ReactNode }) {
  return (
    <PerceptionProvider>
      <PerceptionSensorBridge />
      {children}
    </PerceptionProvider>
  );
}

